async function piAirbnbResendCode(page, preferEmail) {
  if (preferEmail && !(await page.locator('#otp-code-input').count())) {
    await piAirbnbPreferEmailDelivery(page);
  }
  // Airbnb copy on email OTP: "Didn't get it? Send a new code"
  var sendNew = page.getByText(/send a new code/i).first();
  if (await sendNew.count()) {
    await sendNew.click({ force: true, timeout: 4000 }).catch(function () {});
    await page.waitForTimeout(1500);
    return true;
  }
  var hit = await piAirbnbClickMatching(page, [
    'send a new code', '^resend$', 'resend code', 'send again', 'get a new code',
    "didn'?t get it", "didn'?t get a code"
  ], { wait: 2000 });
  return !!hit;
}

