async function piAirbnbResendCode(page) {
  if (!(await page.locator('#otp-code-input').count()) && !(await piAirbnbWaitForEmailOtpPage(page, 2000))) {
    await piAirbnbPreferEmailDelivery(page);
  }
  const body = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ');
  if (/wait 1 minute before requesting a code/i.test(body)) {
    return { ok: false, cooldown: true };
  }
  var sendNew = page.getByText(/send a new code/i).first();
  if (await sendNew.count()) {
    await sendNew.click({ force: true, timeout: 4000 }).catch(function () {});
    await page.waitForTimeout(1500);
    const after = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ');
    return { ok: true, cooldown: /wait 1 minute before requesting a code/i.test(after) };
  }
  return { ok: false, cooldown: false };
}

