async function piAirbnbMarkAwaitingOtp(job) {
  const sent = await piAirbnbPreferEmailDelivery(job.page);
  job.status = 'awaiting_otp';
  await piAirbnbSnapshotOtpMeta(job);
  if (sent === 'email' || (await job.page.locator('#otp-code-input').count())) {
    job.hint = 'Airbnb emailed a code to the host inbox. Use the newest email only. Wait ~1 minute before Resend.';
  } else {
    job.hint = 'Could not confirm Airbnb sent email OTP yet. Tap Resend as email once; check inbox + spam.';
  }
}

