async function piAirbnbLoginWorker(job) {
  const email = process.env.AIRBNB_HOST_EMAIL || '';
  const pass = process.env.AIRBNB_HOST_PASSWORD || '';
  let pw;
  try { pw = require('playwright'); } catch (e) {
    job.status = 'error';
    job.error = 'playwright is not installed on this deploy';
    job.updatedAt = Date.now();
    return;
  }
  try {
    job.status = 'starting';
    job.updatedAt = Date.now();
    const browser = await piAirbnbLaunchBrowser(pw);
    job.browser = browser;
    const context = await piAirbnbNewContext(browser);
    job.context = context;
    const page = await context.newPage();
    job.page = page;

    await page.goto('https://www.airbnb.com/login', { waitUntil: 'domcontentloaded', timeout: 90000 });
    await page.waitForTimeout(1500);
    for (const sel of ['button:has-text("Accept")', 'button:has-text("Accept all")', 'button:has-text("OK")', '[data-testid="accept-btn"]']) {
      const b = page.locator(sel).first();
      if (await b.count()) await b.click({ timeout: 2000 }).catch(function () {});
    }
    const emailInput = page.locator('#phone-or-email, input[name="email"], input[type="email"], input[autocomplete="username"]').first();
    await emailInput.waitFor({ state: 'visible', timeout: 30000 });
    await emailInput.click();
    await emailInput.fill('');
    await emailInput.type(email, { delay: 35 });
    await page.locator('button:has-text("Continue"), button[type="submit"]').first().click();
    await page.waitForTimeout(6500);

    // Always try email OTP first. Stay on that page — do not fill password until the user submits the code.
    const emailed = await piAirbnbPreferEmailDelivery(page);
    if (emailed === 'email' || (await piAirbnbNeedsOtp(page)) || (await page.locator('#otp-code-input').count())) {
      await piAirbnbMarkAwaitingOtp(job);
      return;
    }

    if (await page.locator('input[name="password"], input[type="password"]').count()) {
      await piAirbnbPreferEmailDelivery(page);
      if (await piAirbnbNeedsOtp(page) || (await page.locator('#otp-code-input').count())) {
        await piAirbnbMarkAwaitingOtp(job);
        return;
      }
      await piAirbnbDismissOverlays(page);
      await piAirbnbFillPassword(page, pass);
    }

    if (await piAirbnbNeedsOtp(page) || (await page.locator('#otp-code-input').count())) {
      await piAirbnbMarkAwaitingOtp(job);
      return;
    }

    const bodyText = await page.locator('body').innerText().catch(function () { return ''; });
    if (/airlock|arkose|security check|unusual activity|captcha/i.test(bodyText) && !(await piAirbnbPageLooksLoggedIn(page))) {
      throw new Error('Airbnb Airlock/bot check blocked this login. Retry Connect. If it keeps failing, set PLAYWRIGHT_PROXY_SERVER to a residential proxy.');
    }

    await piAirbnbFinishAndSave(job);
  } catch (e) {
    job.status = 'error';
    job.error = e.message || String(e);
    job.updatedAt = Date.now();
    await piLoginCleanup(job, true);
  }
}

